using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "System.Security.Cryptography", "System.Text.Json", "Microsoft.Extensions", "Microsoft.EntityFrameworkCore",
    ];

    [Fact]
    public void Domain_depends_on_no_other_layer_and_no_technical_namespace()
    {
        var violations = Violations(typeof(Money).Assembly, allowedLayers: []);

        Assert.Empty(violations);
    }

    [Fact]
    public void Application_depends_only_on_Domain_and_no_technical_namespace()
    {
        var violations = Violations(typeof(AuthorizePayment).Assembly, allowedLayers: ["PaymentAuthorization.Domain"]);

        Assert.Empty(violations);
    }

    private static List<string> Violations(Assembly assembly, string[] allowedLayers)
    {
        using var file = File.OpenRead(assembly.Location);
        using var pe = new PEReader(file);
        var md = pe.GetMetadataReader();
        var own = md.GetString(md.GetAssemblyDefinition().Name);
        var found = new List<string>();

        foreach (var handle in md.AssemblyReferences)
        {
            var name = md.GetString(md.GetAssemblyReference(handle).Name);
            if (name.StartsWith("PaymentAuthorization.") && name != own && !allowedLayers.Contains(name))
                found.Add($"{own} references layer {name}");
        }

        foreach (var handle in md.TypeReferences)
        {
            var type = md.GetTypeReference(handle);
            var ns = md.GetString(type.Namespace);
            if (TechnicalNamespaces.Any(t => ns == t || ns.StartsWith(t + ".")))
                found.Add($"{own} uses {ns}.{md.GetString(type.Name)}");
        }

        return found;
    }
}
